CREATE OR REPLACE FUNCTION public.flight_quote(p_aircraft uuid,p_destination text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f fleet_aircraft%ROWTYPE; t aircraft_types%ROWTYPE; a airports%ROWTYPE; b airports%ROWTYPE; nm numeric; mins numeric; fuel numeric; pax integer; gross numeric; landing numeric; handling numeric; maintenance numeric; price numeric; rules jsonb; BEGIN SELECT * INTO f FROM fleet_aircraft WHERE id=p_aircraft AND company_id IN(SELECT id FROM companies WHERE user_id=auth.uid()); IF NOT FOUND THEN RAISE EXCEPTION 'Aircraft not found'; END IF; SELECT * INTO t FROM aircraft_types WHERE id=f.aircraft_type_id; SELECT * INTO a FROM airports WHERE icao=f.location_icao; SELECT * INTO b FROM airports WHERE icao=p_destination; IF NOT FOUND OR a.icao=b.icao THEN RAISE EXCEPTION 'Choose a different destination'; END IF; IF f.status<>'AVAILABLE' THEN RAISE EXCEPTION 'Aircraft is not available'; END IF; IF t.cruise_kts<=0 OR t.fuel_burn_gph<=0 THEN RAISE EXCEPTION 'Invalid aircraft specification'; END IF; nm:=3440.065*2*asin(sqrt(least(1,power(sin(radians(b.lat-a.lat)/2),2)+cos(radians(a.lat))*cos(radians(b.lat))*power(sin(radians(b.lon-a.lon)/2),2)))); IF nm>t.range_nm THEN RAISE EXCEPTION 'Destination is outside aircraft range'; END IF; IF b.longest_runway_ft IS NOT NULL AND b.longest_runway_ft<t.minimum_runway_ft THEN RAISE EXCEPTION 'Destination runway is too short'; END IF; IF a.longest_runway_ft IS NOT NULL AND a.longest_runway_ft<t.minimum_runway_ft THEN RAISE EXCEPTION 'Origin runway is too short'; END IF; IF (t.fuel_type='100LL' AND a.fuel_100ll_available=false) OR (t.fuel_type='Jet-A' AND a.fuel_jeta_available=false) THEN RAISE EXCEPTION 'Required fuel unavailable at origin'; END IF; mins:=nm/t.cruise_kts*60; fuel:=mins/60*t.fuel_burn_gph; IF fuel+economy_number('fuel_reserve_minutes')/60*t.fuel_burn_gph>t.fuel_capacity_gal THEN RAISE EXCEPTION 'Insufficient fuel capacity with reserve'; END IF; pax:=greatest(0,least(t.pax,floor(passenger_stock(a.icao))::int,floor(passenger_capacity(b.icao)*economy_number('transit_cap')-passenger_stock(b.icao))::int)); SELECT jsonb_object_agg(key,value) INTO rules FROM economy_config; gross:=round(pax*(nm*economy_number('fare_per_nm')+coalesce((rules->'charter_by_tier'->>(t.tier-1))::numeric,0)),2); price:=economy_number(CASE WHEN t.fuel_type='100LL' THEN 'fuel_price_100ll' ELSE 'fuel_price_jeta' END); landing:=round(economy_number('landing_base_fee')*(rules->'airport_fee_multipliers'->>(b.size-1))::numeric,2); handling:=round(gross*economy_number('handling_rate')*2,2); maintenance:=round(mins/60*economy_number('maintenance_per_hour'),2); RETURN jsonb_build_object('distance_nm',round(nm,2),'minutes',round(mins,2),'passengers',pax,'revenue',gross,'fuel_gal',round(fuel,4),'fuel_cost',round(fuel*price,2),'landing_fee',landing,'handling_fee',handling,'maintenance',maintenance,'net',gross-round(fuel*price,2)-landing-handling-maintenance,'rules',rules); END $$;
CREATE OR REPLACE FUNCTION public.dispatch_flight(p_aircraft uuid,p_destination text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c companies%ROWTYPE; f fleet_aircraft%ROWTYPE; q jsonb; fid uuid; BEGIN SELECT * INTO c FROM companies WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No company'; END IF; IF NOT coalesce((SELECT (value #>> '{}')::boolean FROM economy_config WHERE key='web_simulation_enabled'),false) THEN RAISE EXCEPTION 'Web simulation is disabled; ACARS connection required'; END IF; SELECT * INTO f FROM fleet_aircraft WHERE id=p_aircraft AND company_id=c.id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Aircraft not found'; END IF; INSERT INTO airport_passenger_pools(airport_icao,stock) SELECT icao,passenger_stock(icao) FROM airports WHERE icao IN(f.location_icao,p_destination) ON CONFLICT DO NOTHING; PERFORM 1 FROM airport_passenger_pools WHERE airport_icao IN(f.location_icao,p_destination) ORDER BY airport_icao FOR UPDATE; q:=flight_quote(p_aircraft,p_destination); IF (q->>'passengers')::int<=0 THEN RAISE EXCEPTION 'No passengers available for this route'; END IF; IF company_balance(c.id)<(q->>'fuel_cost')::numeric+(q->>'landing_fee')::numeric+(q->>'handling_fee')::numeric+(q->>'maintenance')::numeric THEN RAISE EXCEPTION 'Insufficient operating reserve'; END IF; UPDATE airport_passenger_pools SET stock=passenger_stock(airport_icao)-(q->>'passengers')::integer,updated_at=now(),last_departure_at=now() WHERE airport_icao=f.location_icao; INSERT INTO flights(company_id,aircraft_id,origin_icao,destination_icao,passengers,distance_nm,estimated_minutes,estimate,rules_snapshot) VALUES(c.id,f.id,f.location_icao,p_destination,(q->>'passengers')::int,(q->>'distance_nm')::numeric,(q->>'minutes')::numeric,q-'rules',q->'rules') RETURNING id INTO fid; UPDATE fleet_aircraft SET status='DISPATCHED' WHERE id=f.id; RETURN fid; END $$;
CREATE OR REPLACE FUNCTION public.start_test_flight(p_flight uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f flights%ROWTYPE; BEGIN SELECT * INTO f FROM flights WHERE id=p_flight AND company_id IN(SELECT id FROM companies WHERE user_id=auth.uid()) FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Flight not found'; END IF; IF f.execution_source<>'WEB_MANUAL' OR NOT coalesce((SELECT (value #>> '{}')::boolean FROM economy_config WHERE key='web_simulation_enabled'),false) THEN RAISE EXCEPTION 'Test simulation disabled'; END IF; IF f.status='EN_ROUTE' THEN RETURN; END IF; IF f.status<>'DISPATCHED' THEN RAISE EXCEPTION 'Invalid flight state'; END IF; UPDATE flights SET status='EN_ROUTE',departed_at=now() WHERE id=f.id; UPDATE fleet_aircraft SET status='EN_ROUTE' WHERE id=f.aircraft_id; END $$;
CREATE OR REPLACE FUNCTION public.settle_flight(p_flight uuid,p_telemetry jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c companies%ROWTYPE; f flights%ROWTYPE; q jsonb; bal numeric; delta numeric; item record; dissolving integer; remaining numeric; BEGIN SELECT * INTO c FROM companies WHERE user_id=auth.uid() FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'No company'; END IF; SELECT * INTO f FROM flights WHERE id=p_flight AND company_id=c.id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Flight not found'; END IF; IF f.status='COMPLETED' THEN RETURN f.settlement; END IF; IF f.execution_source<>'WEB_MANUAL' THEN RAISE EXCEPTION 'ACARS flights require verified telemetry ingestion'; END IF; IF NOT coalesce((SELECT (value #>> '{}')::boolean FROM economy_config WHERE key='web_simulation_enabled'),false) THEN RAISE EXCEPTION 'Test simulation disabled'; END IF; IF f.status<>'EN_ROUTE' THEN RAISE EXCEPTION 'Flight must be airborne before settlement'; END IF; IF now()<f.departed_at+make_interval(secs=>((f.estimated_minutes*60)/greatest(1,(f.rules_snapshot->>'simulation_time_scale')::numeric))::double precision) THEN RAISE EXCEPTION 'Flight has not arrived yet'; END IF; q:=f.estimate; bal:=company_balance(c.id); FOR item IN SELECT * FROM (VALUES('TICKET_REVENUE','COMPANY_CASH','PASSENGER_REVENUE',(q->>'revenue')::numeric),('FUEL_EXPENSE','FUEL_EXPENSE','COMPANY_CASH',-(q->>'fuel_cost')::numeric),('AIRPORT_FEES','AIRPORT_EXPENSE','COMPANY_CASH',-(q->>'landing_fee')::numeric),('HANDLING_FEES','HANDLING_EXPENSE','COMPANY_CASH',-(q->>'handling_fee')::numeric),('MAINTENANCE_RESERVE','MAINTENANCE_EXPENSE','COMPANY_CASH',-(q->>'maintenance')::numeric)) AS v(kind,debit,credit,change) LOOP delta:=item.change; bal:=bal+delta; INSERT INTO company_ledger(company_id,entry_type,debit_account,credit_account,amount,company_delta,balance_after,description,reference,idempotency_key) VALUES(c.id,item.kind,item.debit,item.credit,abs(delta),delta,bal,item.kind||' – '||f.origin_icao||' → '||f.destination_icao,f.id::text,'flight:'||f.id||':'||item.kind); END LOOP; PERFORM 1 FROM airport_passenger_pools WHERE airport_icao=f.destination_icao FOR UPDATE; dissolving:=round(f.passengers*((f.rules_snapshot->>'dissolve_min')::numeric+((f.rules_snapshot->>'dissolve_max')::numeric-(f.rules_snapshot->>'dissolve_min')::numeric)*random())); remaining:=passenger_stock(f.destination_icao)+f.passengers-dissolving; UPDATE airport_passenger_pools SET stock=least(passenger_capacity(f.destination_icao)*economy_number('transit_cap'),remaining),updated_at=now() WHERE airport_icao=f.destination_icao; UPDATE fleet_aircraft SET status='AVAILABLE',location_icao=f.destination_icao WHERE id=f.aircraft_id; q:=q||jsonb_build_object('balance_after',bal,'dissolved_passengers',dissolving); UPDATE flights SET status='COMPLETED',completed_at=now(),telemetry=jsonb_build_object('schema_version',1,'source','WEB_MANUAL','fuel_used_gal',f.estimate->'fuel_gal','destination',f.destination_icao),settlement=q WHERE id=f.id; RETURN q; END $$;
CREATE OR REPLACE FUNCTION public.cancel_test_flight(p_flight uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f flights%ROWTYPE; c uuid; BEGIN SELECT id INTO c FROM companies WHERE user_id=auth.uid() FOR UPDATE; SELECT * INTO f FROM flights WHERE id=p_flight AND company_id=c FOR UPDATE; IF NOT FOUND OR f.status<>'DISPATCHED' THEN RAISE EXCEPTION 'Only pending flights can be cancelled'; END IF; UPDATE airport_passenger_pools SET stock=passenger_stock(airport_icao)+f.passengers,updated_at=now() WHERE airport_icao=f.origin_icao; UPDATE flights SET status='CANCELLED' WHERE id=f.id; UPDATE fleet_aircraft SET status='AVAILABLE' WHERE id=f.aircraft_id; END $$;
REVOKE ALL ON FUNCTION public.flight_quote(uuid,text),public.dispatch_flight(uuid,text),public.start_test_flight(uuid),public.settle_flight(uuid,jsonb),public.cancel_test_flight(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.flight_quote(uuid,text),public.dispatch_flight(uuid,text),public.start_test_flight(uuid),public.settle_flight(uuid,jsonb),public.cancel_test_flight(uuid) TO authenticated;